	t.Run("multiple files", func(t *testing.T) {
		t.Parallel()
		data := []byte(":100644 100644 abc1234 def5678 M\x00file1.go\x00:100644 000000 abc1234 0000000 D\x00file2.go\x00:000000 100644 0000000 abc1234 A\x00file3.go\x00")
