func TestParseDiffTreeOutput(t *testing.T) {
	t.Parallel()

	t.Run("empty output", func(t *testing.T) {
		t.Parallel()
		result := parseDiffTreeOutput(nil)
		if result != nil {
			t.Errorf("expected nil, got %v", result)
		}
	})

	t.Run("single modified file", func(t *testing.T) {
