		"b.go": "line1\n",
	})

	// Last checkpoint: agent added lines to both files
	lastCheckpointTree := buildTestTree(t, map[string]string{
		"a.go": "line1\nagent1\n",
		"b.go": "line1\nagent1\nagent2\n",
	})

